import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTable;
import javax.swing.table.DefaultTableModel;

public class InvoiceTableTotals extends JPanel {

    private final DefaultTableModel model =
            new DefaultTableModel(new Object[] { "Item", "Qty", "Price" }, 0);
    private final JTable items = new JTable(model);
    private final JLabel total = new JLabel("(none)");
    private final JLabel lines = new JLabel("(none)");

    public InvoiceTableTotals() {
        items.setName("items");
        total.setName("total");
        lines.setName("lines");
        add(items);
        add(total);
        add(lines);
        recalculate();
    }

    /** Provided: lets callers edit the rows directly. */
    public DefaultTableModel getModel() {
        return model;
    }

    public void addRow(String name, int qty, double price) {
        model.addRow(new Object[] { name, qty, price });
        recalculate();
    }

    public void recalculate() {
        double sum = 0.0;
        for (int row = 0; row < model.getRowCount(); row++) {
            int qty = ((Number) model.getValueAt(row, 1)).intValue();
            double price = ((Number) model.getValueAt(row, 2)).doubleValue();
            sum += qty * price;
        }
        total.setText(String.format(java.util.Locale.US, "Total: $%.2f", sum));
        lines.setText(model.getRowCount() + " rows");
    }
}
